#include <iostream>
#include <stdexcept>
#include <string>

int lies_zahl(const std::string& text) {
    try {
        return std::stoi(text);
    } catch (const std::invalid_argument&) {
        std::cout << "Keine Zahl: " << text << "\n";
        return 0;
    }
}

int main() {
    std::cout << lies_zahl("42") << "\n";
    std::cout << lies_zahl("abc") << "\n";
    return 0;
}

#include <iostream>
#include <stdexcept>

void pruefe_alter(int alter) {
    if (alter < 0 || alter > 150) {
        throw std::invalid_argument("Alter unplausibel");
    }
    std::cout << "Alter ok: " << alter << "\n";
}

int main() {
    for (int alter : {25, -3}) {
        try {
            pruefe_alter(alter);
        } catch (const std::invalid_argument& e) {
            std::cout << "Fehler: " << e.what() << "\n";
        }
    }
    std::cout << "Programm läuft weiter\n";
    return 0;
}

#include <iostream>
#include <stdexcept>
#include <vector>

int main() {
    std::vector<int> werte = {10, 20, 30};
    try {
        std::cout << werte.at(5) << "\n";
    } catch (const std::out_of_range&) {
        std::cout << "Index außerhalb des Vektors\n";
    }
    std::cout << "Letzter Wert: " << werte.at(werte.size() - 1) << "\n";
    return 0;
}

