#include <iostream>
#include <stdexcept>
#include <string>

// Eigene Fehlerklasse: erbt von std::runtime_error.
class BetragFehler : public std::runtime_error {
public:
    explicit BetragFehler(const std::string& text)
        : std::runtime_error(text) {}
};

void buche(int betrag) {
    if (betrag <= 0) {
        throw BetragFehler("Betrag muss positiv sein");
    }
    std::cout << "Gebucht: " << betrag << "\n";
}

int main() {
    try {
        buche(-5);
    } catch (const std::exception& e) {   // fängt auch die eigene Klasse
        std::cout << "Fehler: " << e.what() << "\n";
    }
    return 0;
}

#include <iostream>
#include <stdexcept>

double teile(double zaehler, double nenner) {
    if (nenner == 0.0) {
        throw std::domain_error("Division durch null");
    }
    return zaehler / nenner;
}

int main() {
    try {
        std::cout << teile(10.0, 4.0) << "\n";
        std::cout << teile(10.0, 0.0) << "\n";
    } catch (const std::domain_error& e) {
        std::cout << "Nicht erlaubt: " << e.what() << "\n";
    } catch (const std::exception& e) {
        std::cout << "Anderer Fehler: " << e.what() << "\n";
    }
    std::cout << "Weiter geht es\n";
    return 0;
}
